//! Hash functions: SHA-1, SHA-256, and SHA-384, SHA-512, SHA-512/224 and
//! SHA-512/256 (FIPS 180-4); and MD5 (RFC 1321).
//!
//! Each one's whole computation is verified assembly: an `init`, `update` and
//! `finalize` that maintain a streaming state representing the message
//! absorbed so far, and pad it and output the digest (see each module). The
//! Rust types, generated by `streaming_hash!`, only keep that state together
//! with the message length, which the contracts take as an argument.

#[cfg(any(target_arch = "x86_64", target_arch = "aarch64"))]
pub mod md5;
#[cfg(any(target_arch = "x86_64", target_arch = "aarch64"))]
pub mod sha1;
#[cfg(any(
    target_arch = "x86_64",
    target_arch = "aarch64",
    target_arch = "arm",
    target_arch = "x86"
))]
pub mod sha256;
#[cfg(any(target_arch = "x86_64", target_arch = "aarch64"))]
pub mod sha512;

/// A hash function with an incremental interface, as used by the
/// constructions that are generic over it (HMAC).
pub trait HashFunction: Clone {
    /// The size of a digest, in bytes.
    const OUTPUT_SIZE: usize;
    /// The size of the input blocks, in bytes (the `B` of HMAC).
    const BLOCK_SIZE: usize;
    /// A digest: `OUTPUT_SIZE` bytes.
    type Output: AsRef<[u8]> + AsMut<[u8]> + Clone;

    /// Starts a new computation.
    fn new() -> Self;
    /// Absorbs `data`.
    fn update(&mut self, data: &[u8]);
    /// Returns the digest of everything absorbed.
    fn finalize(self) -> Self::Output;

    /// The digest of `data`.
    fn digest(data: &[u8]) -> Self::Output {
        let mut h = Self::new();
        h.update(data);
        h.finalize()
    }
}

/// Defines a hash function over verified streaming primitives:
///
/// * `init(state: *mut [u8; STATE])` makes `state` represent the empty
///   message;
/// * `update(state, count: u64, data: *const u8, len: usize, scratch: *mut [u64; SCRATCH])`
///   absorbs `len` bytes into a state representing a message of `count`
///   bytes;
/// * `finalize(state, count: u64, out: *mut [u8; FINAL], scratch)` writes
///   the final hash value, whose first `OUTPUT` bytes are the digest.
///
/// Every region is a distinct Rust object, so none overlaps another or the
/// return address, and none wraps around the end of the address space; the
/// length is kept exactly (`update` panics rather than let it reach 2⁶⁴
/// bytes).
macro_rules! streaming_hash {
    (
        $(#[$doc:meta])*
        $name:ident {
            state: $state:literal,
            scratch: $scratch:literal,
            block: $block:literal,
            output: $output:literal,
            final_hash: $final:literal,
            init: $init:path,
            update: $update:path,
            finalize: $finalize:path $(,)?
        }
    ) => {
        $(#[$doc])*
        ///
        /// Messages are limited to 2⁶⁴ − 1 bytes.
        #[derive(Clone)]
        pub struct $name {
            /// The streaming state, representing the message so far.
            state: [u8; $state],
            /// The message length so far, in bytes.
            length: u64,
        }

        impl Default for $name {
            fn default() -> Self {
                Self::new()
            }
        }

        impl $name {
            /// The size of a digest, in bytes.
            pub const OUTPUT_SIZE: usize = $output;
            /// The size of a message block, in bytes.
            pub const BLOCK_SIZE: usize = $block;

            /// Starts a new computation.
            pub fn new() -> Self {
                let mut state = [0; $state];
                // SAFETY: `state` is valid for writes of its size, and is a
                // distinct object from the return address (on x86-64 and x86)
                // and the argument on the stack (on x86); as a Rust object, it
                // does not wrap around the end of the address space.
                unsafe { $init(&mut state) };
                $name { state, length: 0 }
            }

            /// Absorbs `data`.
            ///
            /// # Panics
            ///
            /// If the message reaches 2⁶⁴ bytes.
            pub fn update(&mut self, data: &[u8]) {
                let length = self
                    .length
                    .checked_add(data.len() as u64)
                    .expect("message too long");
                let mut scratch = [0u64; $scratch];
                // SAFETY: `self.state` is valid for reads and writes of its
                // size, `data` for reads of `data.len()` bytes and `scratch`
                // for reads and writes of its size; they are distinct
                // objects, so they do not overlap each other, the return
                // address (on x86-64 and x86) or the arguments on the stack
                // (on 32-bit ARM and x86), and do not wrap around the end of
                // the address space. `self.length` is the length of the
                // message `self.state` represents.
                unsafe {
                    $update(
                        &mut self.state,
                        self.length,
                        data.as_ptr(),
                        data.len(),
                        &mut scratch,
                    )
                };
                self.length = length;
            }

            /// Pads the message and returns its digest.
            pub fn finalize(mut self) -> [u8; $output] {
                let mut out = [0; $final];
                let mut scratch = [0u64; $scratch];
                // SAFETY: `self.state` is valid for reads and writes of its
                // size, `out` for writes of its size and `scratch` for reads
                // and writes of its size; they are distinct objects, so they
                // do not overlap each other, the return address (on x86-64
                // and x86) or the arguments on the stack (on 32-bit ARM and
                // x86), and do not wrap around the end of the address space.
                // `self.length` is the exact length of the message
                // `self.state` represents.
                unsafe { $finalize(&mut self.state, self.length, &mut out, &mut scratch) };
                let mut digest = [0; $output];
                digest.copy_from_slice(&out[..$output]);
                digest
            }

            /// The digest of `data`.
            pub fn digest(data: &[u8]) -> [u8; $output] {
                let mut h = Self::new();
                h.update(data);
                h.finalize()
            }
        }

        impl $crate::hashes::HashFunction for $name {
            const OUTPUT_SIZE: usize = $name::OUTPUT_SIZE;
            const BLOCK_SIZE: usize = $name::BLOCK_SIZE;
            type Output = [u8; $output];

            fn new() -> Self {
                $name::new()
            }

            fn update(&mut self, data: &[u8]) {
                $name::update(self, data)
            }

            fn finalize(self) -> [u8; $output] {
                $name::finalize(self)
            }
        }
    };
}

use streaming_hash;
